class Solution {
    public java.util.List<Double> averageOfLevels(TreeNode root) {
        java.util.List<Double> result = new java.util.ArrayList<>();
        java.util.Queue<TreeNode> queue = new java.util.LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int size = queue.size();
            double sum = 0;
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                sum += node.val;
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            result.add(sum / size);
        }
        return result;
    }
}

class Solution {
    public java.util.List<Double> averageOfLevels(TreeNode root) {
        java.util.List<Double> sums = new java.util.ArrayList<>();
        java.util.List<Integer> counts = new java.util.ArrayList<>();
        dfs(root, 0, sums, counts);
        java.util.List<Double> result = new java.util.ArrayList<>();
        for (int i = 0; i < sums.size(); i++) {
            result.add(sums.get(i) / counts.get(i));
        }
        return result;
    }

    private void dfs(TreeNode node, int level, java.util.List<Double> sums, java.util.List<Integer> counts) {
        if (node == null) return;
        if (level == sums.size()) {
            sums.add(0.0);
            counts.add(0);
        }
        sums.set(level, sums.get(level) + node.val);
        counts.set(level, counts.get(level) + 1);
        dfs(node.left, level + 1, sums, counts);
        dfs(node.right, level + 1, sums, counts);
    }
}
